  const r = await p.evaluate(() => {
    const w = document.documentElement.clientWidth;
    const bad = [...document.querySelectorAll("main *")].filter(e => { const x = e.getBoundingClientRect(); return x.right > w + 1 && !e.closest(".overflow-x-auto, [class*='overflow-x']"); }).slice(0, 8).map(e => e.tagName + "." + (e.className?.toString?.() || "").slice(0, 60));
    return { scrollW: document.documentElement.scrollWidth, w, bad, lesezeit: (document.body.innerText.match(/\d+ Min\. Lesezeit/) || [])[0] };
  });
  console.log(slug, JSON.stringify(r));
  await p.close();
}
await b.close();
EOF
